CREATE TABLE public.plan_entitlements (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, trial_started_at timestamptz NOT NULL DEFAULT now(), trial_ends_at timestamptz NOT NULL DEFAULT (now() + interval '7 days'), premium_until timestamptz);
GRANT SELECT ON public.plan_entitlements TO authenticated;
GRANT ALL ON public.plan_entitlements TO service_role;
ALTER TABLE public.plan_entitlements ENABLE ROW LEVEL SECURITY;
CREATE POLICY entitlement_owner_read ON public.plan_entitlements FOR SELECT TO authenticated USING (user_id = auth.uid());
INSERT INTO public.plan_entitlements(user_id) SELECT id FROM public.profiles ON CONFLICT DO NOTHING;
CREATE FUNCTION public.initialize_life_trial() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ BEGIN INSERT INTO public.plan_entitlements(user_id) VALUES (NEW.id) ON CONFLICT DO NOTHING; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.initialize_life_trial() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER life_trial_on_profile AFTER INSERT ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.initialize_life_trial();
CREATE TABLE public.weekly_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, week_start date NOT NULL, content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,week_start));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.weekly_reviews TO authenticated;
GRANT ALL ON public.weekly_reviews TO service_role;
ALTER TABLE public.weekly_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY reviews_own ON public.weekly_reviews TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE TABLE public.community_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, content text NOT NULL CHECK(char_length(btrim(content)) BETWEEN 1 AND 2000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, DELETE ON public.community_messages TO authenticated;
GRANT ALL ON public.community_messages TO service_role;
ALTER TABLE public.community_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY community_read ON public.community_messages FOR SELECT TO authenticated USING (true);
CREATE POLICY community_send ON public.community_messages FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid());
CREATE POLICY community_delete_own ON public.community_messages FOR DELETE TO authenticated USING (user_id = auth.uid());
CREATE INDEX community_messages_recent ON public.community_messages(created_at DESC);
CREATE TABLE public.payment_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, provider text NOT NULL CHECK(provider IN ('click','payme')), amount_uzs integer NOT NULL DEFAULT 49000 CHECK(amount_uzs=49000), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','cancelled','failed')), provider_reference text UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.payment_orders TO authenticated;
GRANT ALL ON public.payment_orders TO service_role;
ALTER TABLE public.payment_orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY order_owner_read ON public.payment_orders FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.ai_usage_counters (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, request_times timestamptz[] NOT NULL DEFAULT '{}');
GRANT ALL ON public.ai_usage_counters TO service_role;
ALTER TABLE public.ai_usage_counters ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.claim_life_ai_request() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ DECLARE times timestamptz[]; daily_limit integer; hour_count integer; day_count integer; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; INSERT INTO public.ai_usage_counters(user_id) VALUES(auth.uid()) ON CONFLICT DO NOTHING; SELECT request_times INTO times FROM public.ai_usage_counters WHERE user_id=auth.uid() FOR UPDATE; SELECT coalesce(array_agg(t), '{}'::timestamptz[]) INTO times FROM unnest(times) t WHERE t > now()-interval '24 hours'; SELECT count(*) INTO hour_count FROM unnest(times) t WHERE t > now()-interval '1 hour'; day_count := cardinality(times); SELECT CASE WHEN trial_ends_at > now() OR premium_until > now() THEN 30 ELSE 3 END INTO daily_limit FROM public.plan_entitlements WHERE user_id=auth.uid(); daily_limit := coalesce(daily_limit,3); IF hour_count >= 30 OR day_count >= daily_limit THEN RETURN 0; END IF; UPDATE public.ai_usage_counters SET request_times=array_append(times,now()) WHERE user_id=auth.uid(); INSERT INTO public.ai_requests(user_id) VALUES(auth.uid()); RETURN daily_limit-day_count; END; $$;
REVOKE ALL ON FUNCTION public.claim_life_ai_request() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.claim_life_ai_request() TO authenticated;